package vn.cicca.livetranslator.engine

/*
 * The engine's call and event payloads (formerly generated by pigeon in EngineApi.g.kt). They cross to JS
 * through [EngineWire] and VoiceEngineModule, as the plain objects of android/src/engine/NativeVoiceEngine.ts.
 * Enum values cross as their [wire] names (the TS / Dart names).
 */

enum class MissingKind(val wire: String) {
    SPEECH_MODEL("speechModel"),
    TRANSLATION("translation"),
    TTS_VOICE("ttsVoice");

    companion object {
        fun ofWire(name: String?): MissingKind? = entries.firstOrNull { it.wire == name }
    }
}

enum class AudioSessionKind(val wire: String) {
    INTERRUPTED("interrupted"),
    RESUMED("resumed"),
    ROUTE_CHANGED("routeChanged"),
}

enum class AudioRoute(val wire: String) {
    HEADSET("headset"),
    PHONE_MIC("phoneMic"),
}

enum class MineKind(val wire: String) {
    PARTIAL("partial"),
    FINAL_TEXT("finalText"),
}

data class RecognizerEntryMsg(val language: String, val kinds: List<String>)

data class CapabilitiesMsg(
    val recognizers: List<RecognizerEntryMsg>,
    val translatable: List<String>,
    val vietnameseVoice: Boolean,
)

data class MissingMsg(
    val kind: MissingKind,
    val language: String,
    val from: String? = null,
    val to: String? = null,
)

data class PairMsg(val home: String, val other: String, val generation: Long)

data class MineMsg(val kind: MineKind, val text: String, val startMs: Long, val endMs: Long)

data class TheirsMsg(val text: String, val confidence: Double? = null, val generation: Long)

data class AudioSessionMsg(val kind: AudioSessionKind, val route: AudioRoute? = null)

data class DownloadMsg(
    val item: MissingMsg,
    val progress: Double,
    val done: Boolean,
    val error: String? = null,
)

/**
 * A typed engine failure. JS sees a promise rejection whose `code` is [code], an `EngineErrorCode` name
 * (translateFailed, notReady, downloadFailed).
 */
class EngineException(val code: String, override val message: String? = null) : RuntimeException(message)
